import java.util.*;

public class Main {

	public static void main(String args[]){
		Scanner sc = new Scanner(System.in);

		int w = sc.nextInt(), m = sc.nextInt();
		int a[] = new int[101];

		for(int i=0;i<=100;i++){
			a[i] = m%w;
			m/=w;
		}

		int c = 0;
		boolean s = true;
		for(int i=0;i<=100;i++){
			a[i] += c;
			c = a[i]/w;
			a[i] %= w;

			if(a[i]==1 || a[i]==0){
				continue;
			}
			else if(a[i] == w-1){
				c = 1;
			}
			else
			{
				s = false;
				break;
			}

		}

		System.out.print(s && c!=1?"YES":"NO");

	}
}
